/**
 * Update checks for packaged builds.
 *
 * Configuration comes from one of two places, in order:
 *   1. `UPDATE_FEED_URL` — a generic provider base URL (staging, self-hosted).
 *   2. `app-update.yml` — generated by electron-builder from the `publish`
 *      block, i.e. GitHub Releases for official builds.
 *
 * Unpackaged runs and Linux builds without AppImage never pretend an update is
 * possible: deb/rpm users are told to download the new package instead.
 */
import { existsSync } from "node:fs";

export function describeUpdateSupport({
  isPackaged,
  platform,
  appImagePath,
  feedUrl,
  bundledConfig = false,
}) {
  if (!isPackaged) {
    return {
      supported: false,
      reason: "development",
      message: "Updates are disabled in development builds.",
    };
  }
  if (platform === "linux" && !appImagePath) {
    return {
      supported: false,
      reason: "linux_not_appimage",
      message: "Automatic updates on Linux require the AppImage package.",
    };
  }
  if (!feedUrl && !bundledConfig) {
    return {
      supported: false,
      reason: "feed_missing",
      message: "No update feed is configured for this build.",
    };
  }
  return { supported: true, reason: "ready", message: "" };
}

/** Channel-aware feed URL for the generic provider. */
export function feedUrlFor(baseUrl, channel) {
  if (!baseUrl) return null;
  const trimmed = String(baseUrl).replace(/\/+$/, "");
  const suffix = channel === "beta" ? "/beta" : "";
  return `${trimmed}${suffix}`;
}

export function formatUpdateError(error) {
  const message = String(error?.message ?? error ?? "");
  if (/404|ERR_HTTP_RESPONSE_CODE_FAILURE/i.test(message)) {
    return "The update feed has no release for this platform yet.";
  }
  if (/ENOTFOUND|ECONNREFUSED|EAI_AGAIN|ERR_INTERNET_DISCONNECTED/i.test(message)) {
    return "The update server could not be reached. Check your network and try again.";
  }
  if (/code signature|not signed|signature check/i.test(message)) {
    return "This build is not signed, so updates cannot be verified. Install a signed release.";
  }
  return message.split("\n")[0].slice(0, 300);
}

/**
 * Thin wrapper around electron-updater. Everything that touches the updater
 * lives here so the rest of the shell only sees `check()` and `download()`.
 */
export function createUpdater({
  app,
  autoUpdater,
  dialog,
  getWindow,
  logger,
  feedBaseUrl = null,
  bundledConfigPath = null,
  channel = () => "stable",
}) {
  const bundledConfig = Boolean(bundledConfigPath && existsSync(bundledConfigPath));
  const support = describeUpdateSupport({
    isPackaged: app.isPackaged,
    platform: process.platform,
    appImagePath: process.env.APPIMAGE,
    feedUrl: feedBaseUrl,
    bundledConfig,
  });

  let checking = false;
  let readyVersion = null;

  if (support.supported) {
    autoUpdater.autoDownload = false;
    autoUpdater.autoInstallOnAppQuit = false;
    autoUpdater.logger = {
      info: (message) => logger?.info?.(`[update] ${message}`),
      warn: (message) => logger?.warn?.(`[update] ${message}`),
      error: (message) => logger?.error?.(`[update] ${message}`),
      debug: () => {},
    };
    autoUpdater.on("update-available", (info) => logger?.info(`Update available: ${info.version}`));
    autoUpdater.on("update-not-available", () => logger?.info("No update available"));
    autoUpdater.on("error", (error) => logger?.warn(`Update error: ${error?.message ?? error}`));
  }

  function configureFeed() {
    const selected = channel() === "beta" ? "beta" : "stable";
    autoUpdater.channel = selected === "beta" ? "beta" : "latest";
    autoUpdater.allowPrerelease = selected === "beta";
    if (feedBaseUrl) {
      autoUpdater.setFeedURL({ provider: "generic", url: feedUrlFor(feedBaseUrl, selected) });
    }
  }

  async function check({ interactive = true } = {}) {
    if (!support.supported) {
      if (interactive) {
        await dialog.showMessageBox(getWindow(), {
          type: "info",
          title: "Updates",
          message: support.message,
          detail:
            support.reason === "linux_not_appimage"
              ? "Use the AppImage release for automatic updates, or download the latest deb/rpm from the Releases page."
              : "Only signed, packaged releases can update themselves. Download the latest build from GitHub Releases.",
          buttons: ["OK"],
        });
      }
      return { status: "unsupported", reason: support.reason, message: support.message };
    }
    if (checking) return { status: "checking" };
    checking = true;
    try {
      configureFeed();
      const result = await autoUpdater.checkForUpdates();
      const latest = result?.updateInfo?.version ?? null;
      if (!latest) {
        if (interactive) {
          await dialog.showMessageBox(getWindow(), {
            type: "info",
            title: "Updates",
            message: "You are using the latest version.",
            detail: `Version ${app.getVersion()}`,
            buttons: ["OK"],
          });
        }
        return { status: "current", version: app.getVersion() };
      }
      readyVersion = latest;
      if (interactive) {
        const answer = await dialog.showMessageBox(getWindow(), {
          type: "info",
          title: "Update available",
          message: `Version ${latest} is available.`,
          detail: `You are using ${app.getVersion()}. The download runs in the background; you can keep working.`,
          buttons: ["Download", "Later"],
          defaultId: 0,
          cancelId: 1,
        });
        if (answer.response === 0) void download();
      }
      return { status: "available", version: latest };
    } catch (error) {
      const message = formatUpdateError(error);
      logger?.warn(`Update check failed: ${message}`);
      if (interactive) {
        await dialog.showMessageBox(getWindow(), {
          type: "warning",
          title: "Update check failed",
          message,
          buttons: ["OK"],
        });
      }
      return { status: "error", message };
    } finally {
      checking = false;
    }
  }

  async function download() {
    try {
      await autoUpdater.downloadUpdate();
      const answer = await dialog.showMessageBox(getWindow(), {
        type: "info",
        title: "Update ready",
        message: `Version ${readyVersion ?? "new"} is ready to install.`,
        detail: "The application restarts to finish installing. Save any running work first.",
        buttons: ["Restart and install", "Later"],
        defaultId: 0,
        cancelId: 1,
      });
      if (answer.response === 0) {
        if (typeof autoUpdater.quitAndInstall === "function") {
          autoUpdater.quitAndInstall(false, true);
        }
      }
      return { status: "downloaded" };
    } catch (error) {
      const message = formatUpdateError(error);
      logger?.warn(`Update download failed: ${message}`);
      await dialog.showMessageBox(getWindow(), {
        type: "error",
        title: "Update download failed",
        message,
        buttons: ["OK"],
      });
      return { status: "error", message };
    }
  }

  return { support, check, download };
}
